-- Update venues table to match WO-088 specifications
-- Add unique constraint on name field
ALTER TABLE venues ADD CONSTRAINT venues_name_unique UNIQUE (name);

-- Add indexes for performance
CREATE INDEX IF NOT EXISTS ix_venues_name ON venues (name);
CREATE INDEX IF NOT EXISTS ix_venues_city ON venues (city);
CREATE INDEX IF NOT EXISTS ix_venues_is_active ON venues (is_active);

-- Drop existing constraint, update data, then add proper constraint
ALTER TABLE events DROP CONSTRAINT IF EXISTS events_event_type_check;

-- Update data to match new enum
UPDATE events SET event_type = 'Game' WHERE event_type = 'game';
UPDATE events SET event_type = 'Practice' WHERE event_type = 'practice'; 
UPDATE events SET event_type = 'Tournament' WHERE event_type = 'tournament';

-- Complete the events table updates for WO-088

-- 1. Rename title to name
ALTER TABLE events RENAME COLUMN title TO name;

-- 2. Add new constraint with correct enum values
ALTER TABLE events ADD CONSTRAINT events_event_type_check 
CHECK (event_type IN ('Practice', 'Game', 'Meeting', 'Tournament', 'Other'));

-- 3. Add constraint to ensure start_time < end_time
ALTER TABLE events ADD CONSTRAINT events_start_before_end_check 
CHECK (start_time < end_time);

-- 4. Make created_by_user_id NOT NULL
UPDATE events SET created_by_user_id = 1 WHERE created_by_user_id IS NULL;
ALTER TABLE events ALTER COLUMN created_by_user_id SET NOT NULL;

-- 5. Add performance indexes
CREATE INDEX IF NOT EXISTS ix_events_start_time ON events (start_time);
CREATE INDEX IF NOT EXISTS ix_events_end_time ON events (end_time);
CREATE INDEX IF NOT EXISTS ix_events_event_type ON events (event_type);
CREATE INDEX IF NOT EXISTS ix_events_venue_id ON events (venue_id);
CREATE INDEX IF NOT EXISTS ix_events_is_recurring ON events (is_recurring);
CREATE INDEX IF NOT EXISTS ix_events_created_by_user_id ON events (created_by_user_id);
